import{_ as i,H as t,f as a,i as n}from"./chunks/framework.BH2BK_3i.js";const u=JSON.parse('{"title":"04 | 架构演进：架构是如何跟随业务演进的？","description":"","frontmatter":{},"headers":[{"level":2,"title":"Sharing1.0：单体架构","slug":"sharing1-0-单体架构","link":"#sharing1-0-单体架构","children":[{"level":3,"title":"1.  代码质量差","slug":"_1-代码质量差","link":"#_1-代码质量差","children":[]},{"level":3,"title":"2.  开发效率低","slug":"_2-开发效率低","link":"#_2-开发效率低","children":[]}]},{"level":2,"title":"Sharing2.0：组件化架构","slug":"sharing2-0-组件化架构","link":"#sharing2-0-组件化架构","children":[]},{"level":2,"title":"Sharing3.0：插件化架构","slug":"sharing3-0-插件化架构","link":"#sharing3-0-插件化架构","children":[]},{"level":2,"title":"Sharing4.0：容器化架构","slug":"sharing4-0-容器化架构","link":"#sharing4-0-容器化架构","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大型Android系统重构实战/04｜架构演进：架构是如何跟随业务演进的？.md","filePath":"大型Android系统重构实战/04｜架构演进：架构是如何跟随业务演进的？.md","lastUpdated":1795555367000}'),r={name:"大型Android系统重构实战/04｜架构演进：架构是如何跟随业务演进的？.md"};function s(l,e,E,h,o,p){return t(),a("div",null,[...e[0]||(e[0]=[n('<h1 id="_04-架构演进-架构是如何跟随业务演进的" tabindex="-1">04 | 架构演进：架构是如何跟随业务演进的？ <a class="header-anchor" href="#_04-架构演进-架构是如何跟随业务演进的" aria-label="Permalink to &quot;04 | 架构演进：架构是如何跟随业务演进的？&quot;">​</a></h1><p>你好，我是黄俊彬。上节课，我带你学习了提高遗留系统代码可测试性的方法，今天我们就正式进入到专栏的分析设计篇。</p><p>其实说到分析设计，这里有两个问题是我们必须要先思考清楚的。第一个问题是“从哪里来”，只有清楚了解目前架构设计的问题，才能更好地设计解决问题的方案。否则，我们怎么能保证新的设计可以解决问题呢？</p><p>第二个问题是“到哪里去”，很多时候我们都在谈重构和架构改造，却经常忽略我们到底要将原有的系统重构成什么样子。当然，这一步我们或许不用一点一滴从头开始，参考业内成熟的方案也许是更加可靠高效的方式。</p><p>所以这节课我会通过一个产品的架构演进，带你感受一下架构是如何跟随着业务来演进的。通过这节课的内容，你可以更清楚地了解遗留系统的问题和演进方向，这样在做分析设计时，你的目标会更加清晰，设计也会更加从容。</p><h2 id="sharing1-0-单体架构" tabindex="-1">Sharing1.0：单体架构 <a class="header-anchor" href="#sharing1-0-单体架构" aria-label="Permalink to &quot;Sharing1.0：单体架构&quot;">​</a></h2><p>小菜作为架构师，刚加入到一个新的产品团队 Sharing，Sharing 目前采用的架构是单体架构。在项目初期，团队人员少，业务也相对简单，这种架构很好地支撑了业务的迭代。后面是Sharing1.0 的架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/1.png" alt=""></a></p><p>单体架构是常见的架构模式之一。通常所有开发人员基于单个模块进行开发，所有业务功能都集成在一起打包发布。单体架构非常适合团队规模小、业务复杂度低的产品，在项目起始阶段能快速迭代进行验证。</p><p>但是近几年随着业务的发展，Sharing 团队的成员也急剧扩展，另外业务的复杂度也不断提高。产品经常因为 Bug 问题导致上线延期，团队最后为了交差也只能硬着头皮发布。可想而知，最终的线上质量也堪忧，经常收到用户的投诉。</p><p>在深入地了解了 Sharing 的业务及团队问题后，小菜组织了一场内部的架构回顾会，总结了Sharing 项目两个比较关键的问题。</p><h3 id="_1-代码质量差" tabindex="-1">1. 代码质量差 <a class="header-anchor" href="#_1-代码质量差" aria-label="Permalink to &quot;1.  代码质量差&quot;">​</a></h3><p>因为 Sharing 采用的是单体架构并且缺少相应的架构约束，随着业务的持续演进，代码不断地膨胀和腐坏，所以代码内部的耦合度很高。在这样的基础上修改代码，非常容易牵一发而动全身：修改一个 Bug，又引起另外一个 Bug；开发一个功能，又引起另外一个功能的异常。</p><p>例如，小菜接到一个新的需求，其中获取用户登录信息协议中的一些字段产生了变化，需要进行调整。于是他更新了登录模块中的获取个人信息逻辑和本地的缓存数据，但因为用户表也被其他模块使用了，所以这次的修改就导致了另外一个模块的数据读取异常，页面上无法正常显示数据。</p><p>另外，由于耦合度高，开发人员在扩展新功能的时候会大量采用复制粘贴的方式，导致项目中存在大量的重复代码，当有需求变化时很容易产生散弹式的修改。</p><p>比如说项目中原本有一个查看文件列表的功能，但产品需要扩展一个搜索文件列表的界面。本来基础的文件列表是可以复用的，但因为不好扩展，开发人员就通过复制多一个类来实现新功能。等再接到新需求“文件列表增加大小的展示”，由于之前复制了多个类，就必须要在几个类面同时进行相同的修改。</p><h3 id="_2-开发效率低" tabindex="-1">2. 开发效率低 <a class="header-anchor" href="#_2-开发效率低" aria-label="Permalink to &quot;2.  开发效率低&quot;">​</a></h3><p>在开发阶段，开发人员需要对代码编译打包，然后安装到设备上进行调试。但由于代码量大，编译打包甚至会超过 10 分钟，效率非常低，而且这样的过程一天可能要重复几十次，也就是10 分钟乘以 N 次的低价值工作。</p><p>由于目前 Sharing 团队的规模急剧扩张，加之代码中有很多耦合问题，代码合并冲突就成了开发中的常事。开发人员需要花费大量的时间去解决，代码合入效率非常低。</p><p>此外，对于测试人员来说，每次版本迭代都只能在最后的集成阶段进行大量的手工验证，没办法对某个模块或功能做独立的功能验证，因而测试效率也非常低。</p><h2 id="sharing2-0-组件化架构" tabindex="-1">Sharing2.0：组件化架构 <a class="header-anchor" href="#sharing2-0-组件化架构" aria-label="Permalink to &quot;Sharing2.0：组件化架构&quot;">​</a></h2><p>于是，架构师团队对 Sharing 架构重新进行了设计，这次他们采用的是组件化架构。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/2.png" alt=""></a></p><p>组件化架构采用多个模块开发，将业务和基础功能拆分成多个独立的组件。这样一来，开发人员可以基于不同的模块进行独立开发和编译调试，最后发布时再集成所有组件。而且测试人员可以提前对组件进行功能验收，更快推进测试，避免将所有的测试工作都堆积在最后的集成阶段。</p><p>但需要注意组件化后，复杂度会转移到基础设施之上。这时候我们需要引入路由、注入等框架解决组件依赖及通信，并且还需要引入自动化流水线来降低组件集成的复杂度。</p><p>总之通过新的设计，Sharing 拆分了多个独立的组件。由于组件都是采用二进制的形式集成，依赖上都是采用接口注入的形式，避免了直接的依赖，这也有效地减少了修改代码引起的新问题以及代码合并冲突的问题。</p><h2 id="sharing3-0-插件化架构" tabindex="-1">Sharing3.0：插件化架构 <a class="header-anchor" href="#sharing3-0-插件化架构" aria-label="Permalink to &quot;Sharing3.0：插件化架构&quot;">​</a></h2><p>随着 Sharing2.0 组件化的改造，这种架构很好地支持了团队很长时间的版本迭代。但随着业务的发展，产品需要增加一个特性，那就是部分的功能需要让用户能够动态地升级和卸载。</p><p>经过架构团队的评估，因为有了 2.0 组件化的基础，目前的组件都是相对独立的，所以只需要基于当前的架构引入组件的动态管理机制则可，于是团队设计了新的插件化架构，后面是Sharing3.0 的架构图。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/3.png" alt=""></a></p><p>插件化架构通常是基于组件化架构演化来的，目的就是支持组件的动态加载和升级。这种架构适用于业务复杂度高且需要独立迭代、快速触达用户的产品，它一方面可以有效减少应用的体积，另一方面可以让业务插件进行独立的规划演进。</p><p>但需要注意的是，目前大部分的开源框架都在采用 hook 系统 API 的方式进行插件加载，可能会出现版本兼容性和性能的问题。另外，插件化架构还需要额外引入插件的管理平台，支持插件的版本管理、动态下载等机制。这相比组件的集成管理，复杂度更大。</p><p>下面我们以 Google 官方的 Play Feature Delivery 为例，它的整个工程结构如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/4.png" alt=""></a></p><ul><li>图片来自 Google 开发者官网介绍</li></ul><p>Play Feature Delivery 使用了 App Bundle 的多种高级功能，支持配置安装时分发、按条件分发、按需分发等多种插件更新方式。Android Studio 也支持对整个工程的管理以及编译调试功能，不过唯一的缺点是需要使用 Google Play Core 的库来进管理升级。更多 Play FeatureDelivery 的使用及原理，你如果感兴趣可以参考官网的文档介绍。</p><h2 id="sharing4-0-容器化架构" tabindex="-1">Sharing4.0：容器化架构 <a class="header-anchor" href="#sharing4-0-容器化架构" aria-label="Permalink to &quot;Sharing4.0：容器化架构&quot;">​</a></h2><p>随着市场的日益竞争，团队决定让 Sharing 能够跨平台支持更多的系统，从而满足更多用户的使用场景。为了提高开发的效率，同时控制好投入成本，架构师团队进行了容器化架构的设计，Sharing4.0 架构图如下。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/5.png" alt=""></a></p><p>移动互联时代下，很多产品都需要支持多个平台，如 Android、iOS 等。为了减少跨平台的开发和维护成本，容器化跨平台技术成了目前主流的架构形式之一。在移动应用领域，常见的跨平台技术有 H5、ReactNative 和 Flutter，这些技术都支持编写统一的插件，然后通过容器技术让插件在不同的平台下运行。</p><p>虽然跨平台技术能方便我们复用组件，减少了开发工作，但跨平台的性能和体验通常比原生的要差，并且需要开发人员掌握特定跨平台技术的框架及语言，有一定的学习门槛。当涉及到对本地的硬件能力的访问时，同样也需要使用原生的代码来开发。</p><p>我们以 Flutter 为例，一起来看看它是如何进行跨平台设计的。Flutter 重写了一整套包括底层渲染逻辑和上层开发语言的完整解决方案，不仅可以保证视图渲染在 Android 和 iOS 上的高度一致性，在代码执行效率和渲染性能上也可以媲美原生 App 的体验。Flutter 的整体框架设计如下图所示。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/6.png" alt=""></a></p><ul><li>图片来自 Flutter 开发者官网</li></ul><p>对照框架示意图，我们分别看一下 Flutter 划分了哪三层。</p><ul><li><p>Framework：用 Dart 语言实现的 UI SDK，从上到下包括了基础组件库、图形绘制、手势识别、动画等功能。</p></li><li><p>Engine：用 C/C++ 语言实现 FLutter 引擎，主要包括渲染引擎、文字排版、事件处理、Dart 运行时等功能。</p></li><li><p>Embedder：操作系统适配层，负责实现渲染 Surface 设置、线程设置等功能。</p></li></ul><p>那么原生的平台是如何通过容器来集成 Flutter 的模块呢？Flutter 为各个平台都提供了统一的FlutterEngine API，包含了上述 Flutter 运行需要的所用框架和环境。换句话说，这套框架环境就是我们所说的容器。</p><p>基于这个容器，我们可以非常方便地将部分业务作为独立的模块用 Flutter 来开发，开发完成后这个模块就可以直接运行在不同的平台上。更多关于 Flutter 的内容，你可以参考官网的文档介绍。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>从 Sharing 项目早期的问题来看，遗留系统带来的问题不仅仅降低了研发过程中的效率和质量，最终还导致产品的响应力和表现力都很差。由于代码耦合严重，无法拆分独立的组件。这样导致所有的需求需要统一规划发布， 灵活性差。另外，由于缺少足够的自动化测试覆盖，往往只能在最后的交付阶段进行人工测试，版本发布周期非常长。</p><p>软件的架构就好比一座房子的地基，决定着这座房子能盖多少层楼。同样地，对于遗留系统来说，架构决定着软件产品能走多快、多远。要想解决遗留系统中一系列的问题，架构改造是关键的举措。</p><p>通过 Sharing 的例子我们可以看出，在实际的项目中需要结合团队的规模、产品的发展阶段及定位进行合适的架构选型。随着业务及团队的发展，更合理的架构设计是能持续地演进，而不是一成不变。下表列举了几种架构的的优缺点，你可以对比参考一下各种架构之间的优缺点。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/7.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E5%9E%8BAndroid%E7%B3%BB%E7%BB%9F%E9%87%8D%E6%9E%84%E5%AE%9E%E6%88%98/images/04/7.png" alt=""></a></p><p>正如 Google 在 Play Feature Delivery 概览中说到：在进行插件化之前，首先需要将这些功能从基础应用中分离到功能模块中。所以整个组件化架构的改造是后续插件化、容器化演进的基础，这也是我们专栏的重点内容。下节课我们将通过一个案例，带你一起进行架构分析和架构设计，迈出遗留系统重构的第一步，敬请期待。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>感谢你学完了今天的内容，今天的思考题是这样的：你现在的项目架构有没有什么坑？你是如何来解决的呢？</p><p>欢迎你在留言区与我交流讨论，也欢迎你把它分享给你的同事或朋友，我们一起来高效、高质量交付软件！</p>',57)])])}const d=i(r,[["render",s]]);export{u as __pageData,d as default};
